@font-face { font-family: Inter; src: url("/replays/assets/1dc044f4824f.woff2") format("woff2"); font-weight: 100 900; font-display: block; }:root { --ink: #1C2330; --body: #2E3849; --muted: #5A6881; --blue: #1E47A8; --navy: #0D3880; --navy-deep: #051A49; --panel: #F3F5F7; --line: #E3E6EA; --card-line: #D3D7DE; --field: #838FA5; --secondary: #E8EBEE; --scrim: rgba(28, 35, 48, .48); --ease-out: cubic-bezier(0.23, 1, 0.32, 1); --ease-drawer: cubic-bezier(0.32, 0.72, 0, 1); }* { box-sizing: border-box; }html, body { margin: 0px; }body { font: 400 15px / 22px Inter, -apple-system, system-ui, sans-serif; color: var(--body); background: rgb(255, 255, 255); -webkit-font-smoothing: antialiased; -webkit-tap-highlight-color: transparent; max-width: 430px; margin: 0px auto; min-height: 100vh; }body.locked { overflow: hidden; }button:focus, button:focus-visible, a:focus-visible { outline: none; }button { font: inherit; color: inherit; border: 0px; background: none; padding: 0px; cursor: pointer; }a { color: inherit; text-decoration: none; cursor: pointer; }h1, h2, h3, p { margin: 0px; }.status { position: sticky; top: 0px; z-index: 5; background: rgb(255, 255, 255); height: 47px; display: flex; align-items: center; justify-content: space-between; padding: 6px 30px 0px 38px; color: rgb(0, 0, 0); font: 600 16px / 1 -apple-system, Inter, sans-serif; }.status .icons { display: flex; gap: 6px; align-items: center; }.status svg { fill: currentcolor; }.bar { height: 68px; display: flex; align-items: center; justify-content: space-between; padding: 0px 16px; border-bottom: 1px solid var(--line); background: rgb(255, 255, 255); }.logo { display: flex; align-items: center; gap: 6px; font: 700 23px / 1 Inter, sans-serif; letter-spacing: -0.04em; color: var(--navy-deep); }.disc { width: 32px; height: 32px; border-radius: 50%; background: var(--navy); display: grid; grid-template-columns: repeat(3, 3px); gap: 3px; place-content: center; }.disc i { width: 3px; height: 3px; border-radius: 50%; background: rgb(255, 255, 255); opacity: 0.85; }.disc i:nth-child(1), .disc i:nth-child(3), .disc i:nth-child(7), .disc i:nth-child(9) { opacity: 0.35; }.bar-end { display: flex; align-items: center; gap: 18px; }.link { color: var(--blue); }.bar .link { font-size: 16px; }.menu { fill: var(--body); }.module { padding: 28px 16px 40px; }.module h1 { font: 600 22px / 28px Inter, sans-serif; letter-spacing: -0.01em; color: var(--ink); }.tabs { display: flex; gap: 20px; margin-top: 14px; border-bottom: 1px solid var(--line); overflow-x: auto; scrollbar-width: none; }.tabs::-webkit-scrollbar { display: none; }.tab { position: relative; flex: 0 0 auto; padding: 6px 0px 10px; font-size: 16px; color: var(--muted); transition: color 150ms; }.tab::after { content: ""; position: absolute; left: 0px; right: 0px; bottom: -1px; height: 3px; border-radius: 2px; background: var(--blue); transform: scaleX(0); transition: transform 200ms var(--ease-out); }.tab[aria-selected="true"] { color: var(--blue); }.tab[aria-selected="true"]::after { transform: scaleX(1); }.field-label { display: block; margin-top: 24px; font: 600 14px / 20px Inter, sans-serif; color: var(--ink); }.select { margin-top: 8px; height: 46px; display: flex; align-items: center; gap: 10px; padding: 0px 14px; border: 2px solid var(--field); border-radius: 8px; color: var(--ink); font-size: 16px; }.select .chev { margin-left: auto; }.group { margin-top: 32px; scroll-margin-top: 12px; }.group h2 { font: 600 18px / 24px Inter, sans-serif; color: var(--ink); }.group h2.under { text-decoration: underline 1.5px; text-underline-offset: 4px; }.group > p { margin-top: 8px; font-size: 15px; }.fade { transition: opacity 300ms var(--ease-out), transform 300ms var(--ease-out); }.fade.pre { opacity: 0; transform: translateY(8px); }.fade.pre.from-right { transform: translateX(16px); }.fade.pre.pop { transform: scale(0.97); }.rail { display: flex; gap: 12px; margin: 16px -16px 0px; padding: 0px 16px 2px; overflow-x: auto; scroll-snap-type: x mandatory; scroll-padding: 16px; scrollbar-width: none; }.rail::-webkit-scrollbar { display: none; }.card { flex: 0 0 auto; width: 282px; scroll-snap-align: start; border: 1px solid var(--card-line); border-radius: 16px; padding: 20px; text-align: left; background: rgb(255, 255, 255); transition: transform 150ms var(--ease-out), border-color 150ms ease; }.card:active { transform: scale(0.98); }.card .mark { width: 40px; height: 40px; border-radius: 8px; display: grid; place-items: center; background: var(--panel); margin-bottom: 14px; }.card h3 { font: 600 17px / 23px Inter, sans-serif; color: var(--ink); }.card .by { color: var(--muted); margin-top: 2px; }.card .old-title { font: 600 15px / 21px Inter, sans-serif; color: var(--ink); }.card .partner { color: var(--muted); margin-top: 2px; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }.card .facts { margin-top: 14px; display: grid; gap: 2px; font-size: 15px; }.dots { display: flex; justify-content: center; gap: 8px; margin-top: 14px; }.dots i { width: 8px; height: 8px; border-radius: 50%; background: var(--card-line); transition: background-color 200ms; }.dots i.on { background: var(--body); }.mark { box-shadow: inset 0 0 0 1px var(--line); overflow: hidden; background: rgb(255, 255, 255) !important; }.mark img { display: block; max-width: 76%; max-height: 76%; object-fit: contain; }.mark.fill { box-shadow: none; }.mark.fill img { width: 100%; height: 100%; max-width: none; max-height: none; object-fit: cover; }.btn { height: 48px; border-radius: 10px; display: inline-flex; align-items: center; justify-content: center; gap: 8px; font: 600 16px / 1 Inter, sans-serif; transition: transform 150ms var(--ease-out); }.btn:active { transform: scale(0.97); }.btn.primary { background: var(--body); color: rgb(255, 255, 255); }.btn.secondary { background: var(--secondary); color: var(--ink); }.btn-row { display: grid; grid-template-columns: 1fr 1fr; gap: 12px; }.page { padding: 20px 16px 120px; }.back { display: inline-flex; align-items: center; gap: 8px; color: var(--blue); font-size: 15px; }.page .mark { width: 56px; height: 56px; border-radius: 12px; background: var(--panel); display: grid; place-items: center; margin-top: 20px; }.page h1 { margin-top: 18px; font: 600 24px / 30px Inter, sans-serif; letter-spacing: -0.01em; color: var(--ink); }.page .by { color: var(--muted); margin-top: 2px; font-size: 16px; }.facts-panel { margin-top: 20px; background: var(--panel); border-radius: 16px; padding: 14px 16px; display: grid; gap: 8px; }.facts-panel div { display: flex; justify-content: space-between; gap: 12px; }.facts-panel dt { color: var(--muted); }.facts-panel dd { margin: 0px; color: var(--ink); text-align: right; }.page h2 { margin-top: 28px; font: 600 18px / 24px Inter, sans-serif; color: var(--ink); }.page h2 + p { margin-top: 8px; }.dock { position: fixed; z-index: 6; left: 0px; right: 0px; bottom: 0px; max-width: 430px; margin: 0px auto; padding: 16px 16px 34px; background: rgb(255, 255, 255); border-top: 1px solid var(--line); }.form { display: grid; gap: 16px; margin-top: 20px; }.form label { display: grid; gap: 8px; font: 600 14px / 20px Inter, sans-serif; color: var(--ink); }.input { height: 46px; width: 100%; border: 2px solid var(--field); border-radius: 8px; padding: 0px 14px; font: 400 16px / 1 Inter, sans-serif; color: var(--ink); background: rgb(255, 255, 255); outline: none; transition: border-color 150ms; }.input:focus { border-color: var(--blue); }.pair { display: grid; grid-template-columns: 1fr 1fr; gap: 12px; }.select.input { display: flex; margin-top: 0px; }.scrim { position: fixed; inset: 0px; z-index: 10; background: var(--scrim); opacity: 0; transition: opacity 300ms; }.sheet { position: fixed; z-index: 11; left: 0px; right: 0px; bottom: 0px; max-width: 430px; margin: 0px auto; background: rgb(255, 255, 255); border-radius: 24px 24px 0px 0px; padding: 12px 20px 34px; transform: translateY(100%); transition: transform 420ms var(--ease-drawer); max-height: calc(-60px + 100vh); overflow-y: auto; }.open .scrim { opacity: 1; }.open .sheet { transform: none; }.handle { width: 36px; height: 5px; border-radius: 3px; background: var(--card-line); margin: 0px auto 18px; }.sheet-head { display: grid; grid-template-columns: 48px 1fr 24px; gap: 12px; align-items: start; }.sheet-head .mark { width: 48px; height: 48px; border-radius: 10px; background: var(--panel); display: grid; place-items: center; }.eyebrow { font: 500 13px / 18px Inter, sans-serif; color: var(--muted); }.sheet h2 { font: 600 20px / 26px Inter, sans-serif; color: var(--ink); }.sheet .by { color: var(--muted); }.close { width: 24px; height: 24px; display: grid; place-items: center; }.sheet-body { margin-top: 16px; }.ticks { list-style: none; padding: 0px; margin: 16px 0px 0px; display: grid; gap: 10px; }.ticks li { display: flex; gap: 14px; align-items: center; color: var(--ink); }.ticks svg { width: 18px; flex: 0 0 auto; fill: none; stroke: var(--ink); stroke-width: 1.8; }.sheet .btn-row { margin-top: 24px; }.sheet .form { margin-top: 14px; }.sheet .send { margin-top: 20px; width: 100%; }.sent { text-align: center; padding: 20px 0px 4px; }.sent .tick { width: 56px; height: 56px; border-radius: 50%; background: var(--panel); display: grid; place-items: center; margin: 0px auto 16px; }.sent h3 { font: 600 20px / 26px Inter, sans-serif; color: var(--ink); }.sent p { margin-top: 6px; }.sent .btn { margin-top: 20px; width: 100%; }@media (prefers-reduced-motion: reduce) {
  .sheet { transition: none; }
  .fade { transition: opacity 200ms; }
  .fade.pre { transform: none; }
}
